CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('CITIZEN','AUTHORITY','ADMIN')), phone TEXT, password_hash TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, contact TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS complaints (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, location TEXT, latitude REAL, longitude REAL, ward TEXT, priority TEXT NOT NULL, severity TEXT NOT NULL, status TEXT NOT NULL, assigned_department_id TEXT, cluster_id TEXT, systemic_issue_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS evidence (id TEXT PRIMARY KEY, complaint_id TEXT NOT NULL, type TEXT NOT NULL, file_reference TEXT NOT NULL, description TEXT, created_at TEXT NOT NULL, FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS ai_analyses (id TEXT PRIMARY KEY, complaint_id TEXT NOT NULL, category TEXT NOT NULL, severity TEXT NOT NULL, priority_score INTEGER NOT NULL, confidence REAL NOT NULL, summary TEXT NOT NULL, extracted_entities TEXT NOT NULL, risk_factors TEXT NOT NULL, recommendation TEXT NOT NULL, priority_reason TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS clusters (id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL, ward TEXT NOT NULL, similarity_score REAL NOT NULL, complaint_count INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS systemic_issues (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, ward TEXT NOT NULL, priority TEXT NOT NULL, confidence REAL NOT NULL, complaint_count INTEGER NOT NULL, department_id TEXT, recommended_action TEXT NOT NULL, status TEXT NOT NULL, cluster_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resolutions (id TEXT PRIMARY KEY, complaint_id TEXT NOT NULL, department_id TEXT, action TEXT NOT NULL, notes TEXT, evidence_reference TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, user_id TEXT, type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, metadata TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS complaints_search ON complaints(category,priority,status,ward,created_at);
